``` {.python .cell-code}
import pandas as pd
import lrrcs as lrr
from great_tables import GT

KIKU_GT = dict(table_background_color="transparent",
               table_font_size="0.92rem",
               heading_title_font_size="1.05rem",
               heading_subtitle_font_size="0.85rem",
               source_notes_font_size="0.8rem",
               column_labels_font_weight="bold",
               data_row_padding="4px")

rows = []
for name, phi in (("A", 0.5), ("B", 1.5)):
    out = lrr.price_from_loadings(phi)
    rows.append({"firm": name, "phi": out["loading"], "a1": out["A1"],
                 "prem": out["premium_lr"] * 100,
                 "g_eff": out["g_eff"] * 100,
                 "gordon": out["gordon_return"] * 100})

(
    GT(pd.DataFrame(rows))
    .tab_header(title="Two firms that differ only in the loading")
    .cols_label(firm="firm", phi="phi", a1="A1", prem="premium_lr %",
                g_eff="g_eff %", gordon="gordon %")
    .fmt_number(columns="phi", decimals=1)
    .fmt_number(columns="a1", decimals=1)
    .fmt_number(columns=["prem", "g_eff", "gordon"], decimals=2)
    .tab_source_note("lrr.price_from_loadings on the Table II economy.")
    .tab_options(**KIKU_GT)
)
```

